  ) as v(city, name, lat, lng, is_industrial, pins, boundary)
  join public.cities c on c.name_key = public.city_name_key(v.city) and c.active
 where not exists (
   select 1 from public.neighborhoods n
    where n.city_id = c.id
      and public.neighborhood_name_key(n.name) = public.neighborhood_name_key(v.name))
on conflict (city, name) do nothing;

insert into public.neighborhood_aliases (neighborhood_id, alias, shared, note)
select n.id, v.alias, false, 'השם במאגר רשות המיסים: כל הפינים בתוך המצולע הזה (21.11.2026)'
  from (values
    ('פרדס חנה-כרכור', 'גינת אגוז',    'נווה פרדסים'),
    ('פרדס חנה-כרכור', 'תל רמת כרכור', 'חלומות'),
    ('פרדס חנה-כרכור', 'נווה אשר',     'נווה עולים'),
    ('פרדס חנה-כרכור', 'מרכז כרכור',   'כרכור')
  ) as v(city, hood, alias)
  join public.cities c on c.name_key = public.city_name_key(v.city)
  join public.neighborhoods n on n.city_id = c.id and n.name = v.hood
on conflict (neighborhood_id, alias_key) do nothing;

do $$
declare v_h integer; v_z integer;
begin
  select count(*) into v_h from public.neighborhoods n join public.cities c on c.id = n.city_id
   where c.name_key = public.city_name_key('חדרה') and n.boundary is not null;
  select count(*) into v_z from public.neighborhoods n join public.cities c on c.id = n.city_id
   where c.name_key = public.city_name_key('זכרון יעקב') and n.boundary is not null;
  raise notice 'שכונות עם גבול: חדרה %, זכרון יעקב %', v_h, v_z;
  if v_h < 33 or v_z < 11 then
    raise warning 'צפוי לפחות חדרה 33 וזכרון יעקב 11 - חלק מהמצולעים לא נכנסו';
  end if;
end $$;
